package org.slavicmyths.verify.client;
import java.nio.file.*;import java.util.*;
import net.minecraft.client.*;import net.minecraft.core.BlockPos;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import org.slavicmyths.sivka.*;
/** Two genuine Minecraft processes over loopback TCP; controlled setup, not Survival acquisition. */
public final class Multiplayer269 {
 static boolean started,done,joined,clicked,connected;static int t;static long start;static final BlockPos CHEST=new BlockPos(1002,201,2);static final List<Map<String,Object>> checks=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();static final Set<String> shots=new HashSet<>();static final Path O=Path.of("../../docs/implementation/stabilization269-20261026/"+(Client269.REMOTE?"mp-guest":"mp-host"));
 static void check(boolean ok,String label){checks.add(Map.of("status",ok?"PASS":"FAIL","test",label));System.out.println("QA269_MP "+(ok?"PASS ":"FAIL ")+label);}
 public static void finish(Throwable error){if(done)return;done=true;try{Files.createDirectories(O);out.put("checks",checks);out.put("status",error==null&&checks.stream().noneMatch(x->x.get("status").equals("FAIL"))?"PASS_NETWORK_SCOPE":"FAIL");out.put("error",error==null?null:error.toString());out.put("scope","two real Minecraft clients; loopback TCP, ownership and shared chest race only; natural Survival/ritual MP NOT_RUN");Files.writeString(O.resolve("receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(error!=null)error.printStackTrace();}catch(Exception ex){ex.printStackTrace();}Minecraft.getInstance().stop();}
 static void openChest(Minecraft mc){mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(CHEST),net.minecraft.core.Direction.UP,CHEST,false));}
 public static void tick(Minecraft mc){if(done)return;try{
  if(!started){started=true;start=System.nanoTime();out.put("master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get());}
  if(System.nanoTime()-start>240_000_000_000L)throw new IllegalStateException("two-client timeout");
  if(mc.player==null||mc.level==null){if(connected)finish(null);return;}connected=true;Client269.ready=true;
  if(Client269.REMOTE){
   var horses=mc.level.getEntitiesOfClass(SivkaEntity.class,mc.player.getBoundingBox().inflate(32));if(horses.isEmpty())return;var horse=horses.getFirst();t++;
   if(t==1){check(mc.getSingleplayerServer()==null,"guest has no integrated server; genuine remote client");out.put("remote_address",mc.getConnection().getConnection().getRemoteAddress().toString());check(mc.player.getGameProfile().getName().equals("QA269Guest"),"second real client has distinct player profile");}
   if(t==15){mc.gameMode.interact(mc.player,horse,InteractionHand.MAIN_HAND);net.neoforged.neoforge.network.PacketDistributor.sendToServer(new SivkaNetwork.Input(horse.getId(),123456,1,0,90,true,true,false));}
   if(t==50)check(mc.player.getVehicle()==null,"foreign client cannot mount or hijack unoccupied owner horse");
   if(t==110)openChest(mc);
   if(t==145)check(mc.player.containerMenu instanceof ChestMenu,"guest opens actual shared chest GUI over TCP");
   if(t>=160&&!clicked&&mc.level.getGameTime()%40==0&&mc.player.containerMenu instanceof ChestMenu){clicked=true;out.put("pickup_client_game_time",mc.level.getGameTime());mc.gameMode.handleInventoryMouseClick(mc.player.containerMenu.containerId,0,0,ClickType.PICKUP,mc.player);}
   if(t==225)check(clicked,"guest sent real chest pickup packet");
   if(t==450)finish(null);return;
  }
  var server=mc.getSingleplayerServer();if(server==null)return;
  if(!joined&&Client269.horse==null){joined=true;server.execute(()->{try{var p=server.getPlayerList().getPlayers().getFirst();var w=p.serverLevel();p.stopRiding();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setNoGravity(true);p.getInventory().clearContent();p.teleportTo(w,1000.5,201,2.5,0,0);var h=SivkaContent.ENTITY.get().create(w);h.moveTo(1000.5,201,2.5,0,0);h.setNoAi(true);var b=new SivkaBonds.Bond(p.getUUID());b.stage=7;b.entity=h.getUUID();SivkaBonds.get(w).bonds.put(p.getUUID(),b);SivkaBonds.get(w).setDirty();h.owner=p.getUUID();h.bond=b.id;h.generation=b.generation;w.addFreshEntity(h);p.startRiding(h,true);Client269.horse=h;w.setBlock(CHEST,Blocks.CHEST.defaultBlockState(),3);var chest=(ChestBlockEntity)w.getBlockEntity(CHEST);chest.clearContent();chest.setItem(0,new ItemStack(Items.DIAMOND,3));server.setUsesAuthentication(false);server.getConnection().startTcpServerListener(java.net.InetAddress.getLoopbackAddress(),25770);Files.createDirectories(O);Files.writeString(O.resolve("listening.txt"),"127.0.0.1:25770; real integrated server TCP");System.out.println("QA269_MP_HOST_LISTENING");}catch(Throwable ex){mc.execute(()->finish(ex));}});}
  if(Client269.horse==null||server.getPlayerList().getPlayerCount()<2)return;t++;
  if(t==1){check(server.getPlayerList().getPlayerCount()==2,"two real connections registered in native PlayerList");out.put("players",server.getPlayerList().getPlayers().stream().map(p->p.getGameProfile().getName()).toList());server.execute(()->{var guest=server.getPlayerList().getPlayers().stream().filter(p->p.getGameProfile().getName().equals("QA269Guest")).findFirst().orElseThrow();guest.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);guest.setNoGravity(true);guest.getInventory().clearContent();var owner=server.getPlayerList().getPlayers().stream().filter(q->q.getGameProfile().getName().equals("Dev")).findFirst().orElseThrow();owner.stopRiding();owner.teleportTo(server.overworld(),1000.5,201,.5,0,0);Client269.horse.renewedInteraction();guest.teleportTo(server.overworld(),1003.0,201,3.5,90,0);});}
  if(t==70){check(!Client269.horse.isVehicle(),"guest mount request rejected while owner seat was empty");check(Math.abs(Client269.horse.getYRot())<1,"foreign input packet cannot steer canonical mount");var local=mc.level.getEntitiesOfClass(SivkaEntity.class,mc.player.getBoundingBox().inflate(20)).stream().filter(h->h.getUUID().equals(Client269.horse.getUUID())).findFirst().orElseThrow();mc.gameMode.interact(mc.player,local,InteractionHand.MAIN_HAND);}
  if(t==100)check(server.getPlayerList().getPlayers().stream().filter(p->p.getGameProfile().getName().equals("Dev")).findFirst().orElseThrow().getVehicle()==Client269.horse,"owner reclaims horse through real client interaction packet");
  if(t==120)openChest(mc);
  if(t==150)check(mc.player.containerMenu instanceof ChestMenu,"host opens actual shared chest GUI");
  if(t>=160&&!clicked&&mc.level.getGameTime()%40==0&&mc.player.containerMenu instanceof ChestMenu){clicked=true;out.put("pickup_client_game_time",mc.level.getGameTime());mc.gameMode.handleInventoryMouseClick(mc.player.containerMenu.containerId,0,0,ClickType.PICKUP,mc.player);}
  if(t==230)server.execute(()->{try{int total=0;for(var p:server.getPlayerList().getPlayers())total+=p.getInventory().countItem(Items.DIAMOND)+(p.containerMenu.getCarried().is(Items.DIAMOND)?p.containerMenu.getCarried().getCount():0);var chest=(ChestBlockEntity)server.overworld().getBlockEntity(CHEST);for(int i=0;i<chest.getContainerSize();i++)if(chest.getItem(i).is(Items.DIAMOND))total+=chest.getItem(i).getCount();out.put("server_total_diamonds_after_two_pickups",total);check(total==3,"two actual clients preserve exactly3diamonds across cursors/inventories/chest");check(chest.getItem(0).isEmpty(),"shared slot taken once and remains empty");check(server.getPlayerList().getPlayerCount()==2,"both network clients remain connected for final shared-state check");}catch(Throwable ex){mc.execute(()->finish(ex));}});
  if(t==270){check(clicked,"host sent real chest pickup packet");finish(null);}
 }catch(Throwable ex){finish(ex);}}
 public static void capture(Minecraft mc){if(done||mc.level==null||t<150||t>180||!shots.add("shared-chest"))return;try{Files.createDirectories(O);try(var im=Screenshot.takeScreenshot(mc.getMainRenderTarget())){im.writeToFile(O.resolve("shared-chest.png"));}}catch(Exception ex){finish(ex);}}
}
